using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.NTF.Notificaciones;namespace GraphApi.Services.NTF.Notificaciones{    public class NotificacionesService : INotificacionesService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public NotificacionesService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadNotificaciones>> GetNotificaciones(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM ntf.Notificaciones (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadNotificaciones>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetNotificacionesDynamic(            int? notificacionID,            int? usuarioID,            string? titulo,            string? mensaje,            bool? leido,            DateTime? fechaCreacionNotificacion,            int? tipoNotificacionID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "NotificacionID, UsuarioID, Titulo, Mensaje, Leido, FechaCreacionNotificacion, TipoNotificacionID, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM ntf.Notificaciones (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (notificacionID.HasValue)            {                vSql.Append(" AND NotificacionID = @NotificacionID");                vParameters.Add("NotificacionID",notificacionID);            }            if (!string.IsNullOrWhiteSpace(titulo))            {                vSql.Append(" AND Titulo LIKE @Titulo");                vParameters.Add("Titulo",$"%{titulo}%");            }            if (!string.IsNullOrWhiteSpace(mensaje))            {                vSql.Append(" AND Mensaje LIKE @Mensaje");                vParameters.Add("Mensaje",$"%{mensaje}%");            }            if (leido.HasValue)            {                vSql.Append(" AND Leido = @Leido");                vParameters.Add("Leido", leido.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadNotificaciones> CreateNotificaciones(clCreateNotificaciones objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO ntf.Notificaciones                (UsuarioID, Titulo, Mensaje, Leido, FechaCreacionNotificacion, TipoNotificacionID, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@UsuarioID, @Titulo, @Mensaje, @Leido, @FechaCreacionNotificacion, @TipoNotificacionID, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.UsuarioID,                objInput.Titulo,                objInput.Mensaje,                objInput.Leido,                objInput.FechaCreacionNotificacion,                objInput.TipoNotificacionID,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT NotificacionID, UsuarioID, Titulo, Mensaje, Leido, FechaCreacionNotificacion, TipoNotificacionID, bEliminado                FROM ntf.Notificaciones (NOLOCK)                WHERE NotificacionID = @NotificacionID;";            var vReadParams = new { NotificacionID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadNotificaciones>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Notificacione con ID {vNewId}.");            return vCreated;        }        public async Task<clReadNotificaciones?> UpdateNotificaciones(clUpdateNotificaciones objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("NotificacionID", objInput.NotificacionID);            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.Titulo is not null)            {                vSets.Add("Titulo = @Titulo");                vParameters.Add("Titulo", objInput.Titulo);            }            if (objInput.Mensaje is not null)            {                vSets.Add("Mensaje = @Mensaje");                vParameters.Add("Mensaje", objInput.Mensaje);            }            if (objInput.Leido != null)            {                vSets.Add("Leido = @Leido");                vParameters.Add("Leido", objInput.Leido);            }            if (objInput.FechaCreacionNotificacion != null)            {                vSets.Add("FechaCreacionNotificacion = @FechaCreacionNotificacion");                vParameters.Add("FechaCreacionNotificacion", objInput.FechaCreacionNotificacion);            }            if (objInput.TipoNotificacionID != null)            {                vSets.Add("TipoNotificacionID = @TipoNotificacionID");                vParameters.Add("TipoNotificacionID", objInput.TipoNotificacionID);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE ntf.Notificaciones                SET {vSetClause}                WHERE NotificacionID = @NotificacionID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT NotificacionID, UsuarioID, Titulo, Mensaje, Leido, FechaCreacionNotificacion, TipoNotificacionID, bEliminado                FROM ntf.Notificaciones (NOLOCK)                WHERE NotificacionID = @NotificacionID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadNotificaciones>(sSelect, new {  objInput.NotificacionID });        }        public async Task<bool> DeleteNotificaciones(int nNotificacionesID)        {            const string sSql = @"                DELETE FROM ntf.Notificaciones                WHERE NotificacionID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nNotificacionesID });            return vAffected > 0;        }    }}